class Animal {
  constructor(name) {
    this.name = name;
  }
  speak() {
    return this.name + " makes a sound";
  }
}
const dog = new Animal("Rex");
console.log(dog.speak());

class Dog extends Animal {
  speak() {
    return this.name + " barks";
  }
}
